# ================================================================
# 3. STAR GENERATOR
# ================================================================

def generate_stars(count, zoom, layer):

    random.seed(42 + count)

    stars = ""

    settings = {
        "far": (0.65, 0.75),
        "middle": (1.05, 0.90),
        "near": (1.50, 1.0)
    }

    base_radius, max_opacity = settings[layer]

    for i in range(count):

        x = random.randint(0, 1600)
        y = random.randint(0, 900)

        radius = random.uniform(
            base_radius * 0.65,
            base_radius * 1.5
        ) * math.sqrt(zoom)

        opacity = random.uniform(0.35, max_opacity)

        # Bright stars and glowing halos

        if i % 15 == 0:

            stars += f"""
            <circle cx="{x}" cy="{y}"
                    r="{radius*4:.2f}"
                    fill="#dceaf4"
                    opacity="0.20"
                    filter="url(#glow)"/>
            """

        stars += f"""
        <circle cx="{x}" cy="{y}"
                r="{radius:.2f}"
                fill="#f4f7fa"
                opacity="{opacity:.2f}"/>
        """

    return stars


# ================================================================
# 4. CENTRAL ASTRONOMICAL GRID
# ================================================================

def generate_grid():

    grid = ""

    # Elliptical orbital rings

    for rx, ry in [
        (75, 28),
        (135, 48),
        (205, 72),
        (275, 98),
        (330, 120)
    ]:

        grid += f"""
        <ellipse cx="800" cy="450"
                 rx="{rx}" ry="{ry}"
                 fill="none"
                 stroke="#c2d0da"
                 stroke-width="1"
                 opacity="0.55"/>
        """

    # Horizontal coordinate lines

    for y in range(-120, 121, 15):

        grid += f"""
        <path d="M 440 {450+y}
                 Q 800 {450+y-35} 1160 {450+y}"
              fill="none"
              stroke="#b8c7d1"
              stroke-width="0.8"
              opacity="0.42"/>
        """

    # Curved vertical coordinate lines

    for x in range(-300, 301, 30):

        grid += f"""
        <path d="M {800+x} 320
                 Q {800+x-75} 450 {800+x} 580"
              fill="none"
              stroke="#b8c7d1"
              stroke-width="0.8"
              opacity="0.42"/>
        """

    # Central glowing point

    grid += """
    <circle cx="800" cy="450" r="24"
            fill="#dce8f0" opacity="0.10"/>

    <circle cx="800" cy="450" r="10"
            fill="#f4f7fa"/>

    <circle cx="800" cy="450" r="35"
            fill="none"
            stroke="#dce8f0"
            opacity="0.55"/>
    """

    return grid


