def generate_galaxy_particles():

    rng = random.Random(2026)
    particles = []

    colors = [
        "#fff3dc",
        "#dce9ff",
        "#b9a5ff",
        "#f5c4dc",
        "#ffffff",
        "#9bbcff"
    ]

    # Background stars across the entire galaxy field
    for i in range(1100):
        x = rng.uniform(0, 1600)
        y = rng.uniform(0, 900)
        radius = rng.choices(
            [rng.uniform(0.35, 0.8),
             rng.uniform(0.8, 1.35),
             rng.uniform(1.35, 2.0)],
            weights=[72, 24, 4]
        )[0]

        color = rng.choice(colors)
        opacity = rng.uniform(0.25, 0.85)

        particles.append(
            f'<circle cx="{x:.1f}" cy="{y:.1f}" '
            f'r="{radius:.2f}" fill="{color}" '
            f'opacity="{opacity:.2f}"/>'
        )

    # Four logarithmic spiral arms with dense star concentrations
    center_x = 800
    center_y = 450
    arm_count = 4

    for arm in range(arm_count):

        arm_offset = arm * (2 * math.pi / arm_count)

        for i in range(520):

            theta = rng.uniform(0.15, 8.8)

            # Logarithmic spiral
            radius = 15 * math.exp(0.43 * theta)

            # Natural variation around the spiral
            radius += rng.gauss(0, 13 + theta * 1.8)
            angle = theta + arm_offset + rng.gauss(0, 0.035)

            x = center_x + radius * math.cos(angle)
            y = center_y + radius * math.sin(angle) * 0.53

            if not (0 <= x <= 1600 and 0 <= y <= 900):
                continue

            star_radius = rng.choices(
                [rng.uniform(0.45, 0.9),
                 rng.uniform(0.9, 1.6),
                 rng.uniform(1.6, 2.7)],
                weights=[55, 37, 8]
            )[0]

            color = rng.choice(colors)
            opacity = rng.uniform(0.35, 0.95)

            particles.append(
                f'<circle cx="{x:.1f}" cy="{y:.1f}" '
                f'r="{star_radius:.2f}" fill="{color}" '
                f'opacity="{opacity:.2f}"/>'
            )

            # Occasional brighter star clusters
            if i % 38 == 0:
                cluster_radius = rng.uniform(3, 7)

                particles.append(
                    f'<circle cx="{x:.1f}" cy="{y:.1f}" '
                    f'r="{cluster_radius:.1f}" '
                    f'fill="#b9a5ff" opacity="0.10"/>'
                )

    # Dense golden and white stars around the galactic core
    for i in range(380):

        angle = rng.uniform(0, 2 * math.pi)
        radius = abs(rng.gauss(0, 72))

        x = center_x + math.cos(angle) * radius
        y = center_y + math.sin(angle) * radius * 0.65

        star_radius = rng.uniform(0.45, 1.8)

        particles.append(
            f'<circle cx="{x:.1f}" cy="{y:.1f}" '
            f'r="{star_radius:.2f}" fill="#fff0d2" '
            f'opacity="{rng.uniform(0.35, 0.9):.2f}"/>'
        )

    return "\\n".join(particles)


