def expansion_table_choices(group):
    if group == "Repeat observations":
        return [
            "Available D1 Pointings",
            "Near-Identical Repeat Observations",
            "Verified Repeat Sky Overlaps",
            "Independent Pointing Geometry",
            "Selected Observation Headers",
        ]
    if group == "Detector and calibration":
        return [
            "Six-Detector Epoch Comparison",
            "Six-Detector WCS Alignment",
            "Six-Detector Spatial Residuals",
            "Six-Detector Horizontal Profiles",
            "Six-Detector Sky Footprints",
            "Detector Pair Overlap",
            "Detector Wavelength Coverage",
            "ePSF Wavelength Calibration",
            "ePSF Metadata Comparison",
            "ePSF Spatial Analysis",
            "ePSF Y-Position Profile",
        ]
    if group == "Quality and residuals":
        return [
            "Detector 1 Quality Masks",
            "Common Quality Mask",
            "Decoded Detector Flags",
            "Detector 1 Spatial Residuals",
            "Region Component Comparison",
            "Brightness and Variance Ratios",
            "High-Confidence Residual Cells",
            "Independent Pointing X Profile",
            "Pointing 367-1 Row Profile",
            "Residual Edge Profile",
        ]
    return []

def load_expansion_table(group, table_name):
    catalogue_tables = expansion_table_choices(group)

    if table_name not in catalogue_tables:
        result_names = list(EXPANSION_RESULT_TABLES)
        if group != "Quality and residuals" or table_name not in result_names:
            return "Select a dataset from this section.", pd.DataFrame()

    if table_name in EXPANSION_CATALOGUE_TABLES:
        path = os.path.join(
            MULTI_CATALOGUE,
            EXPANSION_CATALOGUE_TABLES[table_name]
        )
    elif table_name in EXPANSION_RESULT_TABLES:
        path = os.path.join(
            MULTI_RESULTS,
            EXPANSION_RESULT_TABLES[table_name]
        )
    else:
        return "Dataset configuration not found.", pd.DataFrame()

    if not os.path.exists(path):
        return f"**Dataset unavailable:** `{os.path.basename(path)}`", pd.DataFrame()

    try:
        preview = pd.read_csv(path, nrows=301)
        has_more = len(preview) > 300
        preview = preview.head(300)

        note = (
            "Showing the first 300 rows. Use the source CSV in the project "
            "folder for the complete dataset."
            if has_more
            else f"Showing all {len(preview):,} rows."
        )

        description = (
            f"### {table_name}\n\n"
            f"**Columns:** {len(preview.columns)}  \n"
            f"**Preview:** {note}  \n"
            f"**Source:** `{os.path.basename(path)}`"
        )

        return description, preview

    except Exception as error:
        return f"**Could not load dataset:** {error}", pd.DataFrame()

def load_expansion_plot(plot_name):
    filename = EXPANSION_PLOT_FILES.get(plot_name)
    if not filename:
        return None

    path = os.path.join(MULTI_PLOTS, filename)
    return path if os.path.exists(path) else None

