def cw_load_archive_fits(relative_path):
    import numpy as np
    from astropy.io import fits
    from PIL import Image as PILImage

    path = cw_archive_path(relative_path)
    preview_path = None
    hdu_details = []
    preview_array = None
    selected_header = {}

    with fits.open(path, memmap=True) as hdul:
        for index, hdu in enumerate(hdul):
            shape = getattr(hdu, "shape", None)
            hdu_details.append(
                f"- HDU {index}: **{hdu.name}**, shape `{shape}`"
            )

            if preview_array is None and hdu.data is not None:
                arr = np.asarray(hdu.data)
                if arr.ndim >= 2:
                    while arr.ndim > 2:
                        arr = arr[0]
                    if arr.ndim == 2:
                        preview_array = np.asarray(arr, dtype=float)
                        selected_header = hdu.header.copy()

        primary_header = hdul[0].header.copy()

    if preview_array is not None:
        finite = np.isfinite(preview_array)

        if finite.any():
            low, high = np.nanpercentile(preview_array[finite], [1, 99])

            if high <= low:
                high = low + 1

            scaled = np.zeros(preview_array.shape, dtype=np.uint8)
            normalized = np.clip(
                (preview_array - low) / (high - low), 0, 1
            )
            scaled[finite] = (normalized[finite] * 255).astype(np.uint8)

            preview_path = os.path.join(
                "/tmp",
                "cw_fits_preview_" +
                str(abs(hash(relative_path))) + ".png"
            )
            PILImage.fromarray(scaled).save(preview_path)

    bunit = selected_header.get(
        "BUNIT", primary_header.get("BUNIT", "Not specified")
    )
    ctype1 = selected_header.get(
        "CTYPE1", primary_header.get("CTYPE1", "Not specified")
    )
    ctype2 = selected_header.get(
        "CTYPE2", primary_header.get("CTYPE2", "Not specified")
    )

    info = (
        f"### {os.path.basename(relative_path)}\n"
        f"- **Location:** `{relative_path}`\n"
        f"- **Image unit:** `{bunit}`\n"
        f"- **CTYPE1:** `{ctype1}`\n"
        f"- **CTYPE2:** `{ctype2}`\n"
        f"- **HDU structure:**\n" + "\n".join(hdu_details)
    )

    return info, preview_path, path


