def cw_read_object_images():

    import numpy as np
    from astropy.io import fits

    paths = [
        os.path.join(DATA, "2025W18_1B_0162_1_D1.fits"),
        os.path.join(DATA, "aligned_observation2_complete_wcs.fits"),
        os.path.join(DATA, "corrected_difference.fits")
    ]

    with fits.open(paths[0]) as h:
        earlier = np.asarray(h["IMAGE"].data, dtype=float).copy()

    with fits.open(paths[1]) as h:
        later = np.asarray(h["IMAGE"].data, dtype=float).copy()

    with fits.open(paths[2]) as h:
        difference = np.asarray(h[0].data, dtype=float).copy()

    return earlier, later, difference


def cw_make_cutout(image, x, y, size=60):

    import numpy as np

    half = size // 2

    result = np.full((size, size), np.nan)

    x1, x2 = max(0, x-half), min(image.shape[1], x+half)
    y1, y2 = max(0, y-half), min(image.shape[0], y+half)

    if x1 >= x2 or y1 >= y2:
        return result

    target_x1 = x1 - (x-half)
    target_y1 = y1 - (y-half)

    result[
        target_y1:target_y1+(y2-y1),
        target_x1:target_x1+(x2-x1)
    ] = image[y1:y2, x1:x2]

    return result


def cw_render_object_image(image, difference=False):

    import numpy as np

    valid = np.isfinite(image)

    rgb = np.zeros((*image.shape, 3), dtype=float)

    if not valid.any():
        rgb[:] = 0.25
        return (rgb * 255).astype(np.uint8)

    values = image[valid]

    if difference:
        limit = np.nanpercentile(np.abs(values), 99)
        limit = max(float(limit), 1e-12)

        normalized = np.clip(
            (image / limit + 1) / 2, 0, 1
        )

        rgb[..., 0] = normalized
        rgb[..., 1] = 1 - np.abs(2 * normalized - 1)
        rgb[..., 2] = 1 - normalized

    else:
        low, high = np.nanpercentile(values, [2, 98])

        if high <= low:
            high = low + 1e-12

        normalized = np.clip(
            (image - low) / (high - low), 0, 1
        )

        for channel in range(3):
            rgb[..., channel] = normalized

    # Invalid pixels are displayed in grey
    rgb[~valid] = [0.30, 0.30, 0.30]

    return (rgb * 255).astype(np.uint8)


def cw_observe_object(kind, selected):

    import numpy as np

    earlier, later, difference = cw_read_object_images()

    if kind == "Candidate regions":

        region_id = int(selected.split()[-1])

        row = candidates[
            candidates["Region_ID"].astype(int) == region_id
        ].iloc[0]

        x = int(round(row["Center_X"]))
        y = int(round(row["Center_Y"]))

        x1, y1 = x, y
        x2, y2 = x, y

        object_details = f"""
### Candidate Region {region_id}

- **Pixel position:** X = {x}, Y = {y}
- **Candidate pixels:** {int(row["Pixel_Count"])}
- **Distance from edge:** {row["Edge_Distance"]:.1f} pixels
- **Source type:** Exploratory residual candidate
"""

    else:

        star_number = int(selected.split()[-1])
        reference_data = pd.read_csv(
            os.path.join(RESULTS, "clean_reference_stars.csv")
        )

        row = reference_data.iloc[star_number - 1]

        x1 = int(round(row["X1"]))
        y1 = int(round(row["Y1"]))
        x2 = int(round(row["X2"]))
        y2 = int(round(row["Y2"]))

        x, y = x2, y2

        object_details = f"""
### Reference Star {star_number:03d}

- **Earlier position:** ({x1}, {y1})
- **Later position:** ({x2}, {y2})
- **Match distance:** {row["Match_Distance"]:.2f} pixels
- **Earlier aperture flux:** {row["Flux1"]:.4f}
- **Later aperture flux:** {row["Flux2"]:.4f}

These are measured aperture fluxes. Differences should not
automatically be interpreted as confirmed physical variability.
"""

    earlier_cut = cw_make_cutout(earlier, x1, y1)
    later_cut = cw_make_cutout(later, x2, y2)
    difference_cut = cw_make_cutout(difference, x2, y2)

    valid_count = int(np.isfinite(difference_cut).sum())
    coverage = valid_count / difference_cut.size * 100

    details = object_details + f"""

### Difference image coverage

- **Valid pixels:** {valid_count} / {difference_cut.size}
- **Coverage:** {coverage:.2f}%

Grey areas indicate invalid or unavailable pixels.

**Scientific note:** Residual regions are exploratory candidates,
not confirmed transient objects. Image differences can also arise
from calibration, background, detector effects, or noise.
"""

    return (
        cw_render_object_image(earlier_cut),
        cw_render_object_image(later_cut),
        cw_render_object_image(difference_cut, difference=True),
        details
    )


def cw_switch_object_type(kind):

    choices = cw_object_choices(kind)
    first = choices[0]

    outputs = cw_observe_object(kind, first)

    return (
        gr.update(choices=choices, value=first),
        *outputs
    )



